# 7급 CH2 대명사 (11~20) 2차 감수
X(7, 11, r="대명사의 뜻: 주격(I, he, she, we, they)은 ‘~은/는’, 소유격(my, his, her, its, our, their)은 ‘~의’, 목적격(me, him, us, them)은 ‘~을/를’.",
  n=["our는 ‘우리의’가 맞으므로", "he는 ‘그는’이 맞으므로", "its는 소유격이라 ‘그것의’로 옮겨야 하므로", "her는 ‘그녀의’가 맞으므로", "I는 ‘나는’이 맞으므로"],
  st="① 대명사마다 주격·소유격·목적격 가운데 무엇인지 가른다. → ② 우리말의 끝(‘~는’, ‘~의’, ‘~를’)이 그 격과 맞는지 본다. → ③ {0} 정답은 {a}.",
  R="its는 소유격인데 ‘그것은’(주격)으로 옮겼다.", B="me는 목적격인데 ‘나는’(주격)으로 옮겼다.", C="his는 소유격인데 ‘그는’(주격)으로 옮겼다.", D="them은 목적격인데 ‘그들의’(소유격)로 옮겼다.",
  E="our는 소유격인데 ‘우리를’(목적격)로 옮겼다.", F="their는 소유격인데 ‘그들은’(주격)으로 옮겼다.")
RV(7, 11, "BCEF", v="수정(내용)", why="정답 유일 확인. 다만 같은 우리말 뜻이 두 보기에 나와 둘 중 하나가 답이라는 단서가 된다(B: she - 그녀는 / her - 그녀는, C: he - 그는 / his - 그는, E: our - 우리를 / us - 우리를, F: their - 그들은 / they - 그들은). B의 정답은 원문항 ④(her - 그녀의)의 틀린 꼴이고, B·F에는 원문항과 똑같은 짝(our - 우리의, her - 그녀의)도 있다.", fix="같은 뜻이 두 번 나오지 않게, 원문항과 겹치는 짝도 바꿈")

X(7, 12, r="I - me는 주격 - 목적격의 짝이다. 같은 관계: he - him, she - her, we - us, they - them, you - you, it - it. hers, ours, theirs, mine은 소유대명사, his·its는 소유격이다.",
  n=["he - him은 주격 - 목적격이므로", "hers는 목적격(her)이 아니라 소유대명사이므로", "they - them은 주격 - 목적격이므로", "you는 주격과 목적격이 같으므로", "it은 주격과 목적격이 같으므로"],
  st="① <보기>의 관계를 정한다: {0}은 주격 - 목적격(‘~는’ - ‘~를’)이다. → ② 보기마다 둘째 낱말이 목적격인지 본다. → ③ {1} 정답은 {a}.",
  R=("I - me", "hers는 ‘그녀의 것’(소유대명사)이다. 목적격은 her다."), B=("I - me", "theirs는 ‘그들의 것’이다. 목적격은 them이다."), C=("I - me", "his는 ‘그의’다. 목적격은 him이다."), D=("I - me", "ours는 ‘우리의 것’이다. 목적격은 us다."),
  E=("I - me", "its는 ‘그것의’(소유격)다. 목적격은 it이다."), F=("they - them", "mine은 ‘나의 것’이다. 목적격은 me다."))

X(7, 13, r="명사를 대명사로 바꿀 때: 나를 포함한 여럿은 we, 너를 포함한 여럿은 you, 그 밖의 여럿은 they, 남자 한 명은 he, 여자 한 명은 she, ~’s는 his/her.",
  n=["Bruce and I에는 나(I)가 들어 있어 We로 바꿔야 하므로", "두 사람을 They로 바르게 바꿨으므로", "여자 한 명을 She로 바르게 바꿨으므로", "남자 Tom의 소유를 His로 바르게 바꿨으므로", "나를 포함한 여럿을 We로 바르게 바꿨으므로"],
  st="① 밑줄 친 말에 I(나)나 You(너)가 들어 있는지, 몇 명인지, 남자인지 여자인지 본다. → ② 화살표 뒤의 대명사와 맞는지 견준다. → ③ {0} 정답은 {n}.",
  R="①의 Bruce and I는 We다.", B="③의 My brother and I는 We다.", C="④의 Ben은 남자라 His다.", D="②의 Jane and Mina는 나를 포함하지 않아 They다.", E="①의 My father는 남자라 He다.", F="⑤의 You and your brother는 You다.")
RV(7, 13, "BEF", v="수정(내용)", why="정답 유일 확인. 다만 틀린 문장과 짜임이 같은 옳은 문장이 함께 있어 둘만 견주면 답이 나온다(B: My brother and I → They / My sister and I → We, E: My father → She / My mother → She, F: Jane and I → They / My sister and I → We). B와 F는 틀린 꼴(~ and I → They)과 위치(①)가 서로 같고 원문항과도 같은 종류다. 밑줄이 없고 발문·제시문도 다르다.", fix="짝 문장을 다른 문장으로, F는 다른 종류의 오류로")

X(7, 14, r="명사 + ’s(~의)는 소유격 대명사로 바꾼다: 남자 한 명 his, 여자 한 명 her, 사물·동물 its, 여럿 their.",
  n=["its는 사물·동물의 소유이므로", "their는 여럿의 소유이므로", "our는 ‘우리의’이므로", "Lucy는 여자 한 명이라 her로 바꾸므로", "my는 ‘나의’이므로"],
  st="① 밑줄 친 말이 누구(무엇)의 것을 말하는지 본다: {0}. → ② 그에 맞는 소유격은 {a}. → ③ 정답은 {n}.",
  R="Lucy(여자 한 명)", B="my parents(두 분)", C="Tom and Jane(두 사람)", D="Leo(남자 한 명)", E="the bird(동물 한 마리)", F="my sister(여자 한 명)")
RV(7, 14, "E", v="수정(내용)", why="정답 ② his 유일 확인. 다만 문장의 짜임(Jane is Ben's friend.)과 정답(his)이 D(Mina is Leo's sister. — his)와 같다(유형 간 중복). 밑줄이 없고 발문도 길어졌다.", fix="문장을 바꿔 다른 소유격이 정답이 되게")

X(7, 15, r="주어 자리에는 주격(I, you, he, she, we, they), 명사 앞에는 소유격(my, your, his, her, our, their)을 쓴다.",
  n=["주어 자리에 He, 명사 pizza 앞에 His가 알맞으므로", "(A)와 (B)가 서로 바뀌었으므로", "(B) 명사 앞에 목적격 Him을 쓸 수 없으므로", "(A) 주어 자리에 목적격 Him을 쓸 수 없으므로", "(B) 명사 앞에는 주격 He가 아니라 소유격 His를 쓰므로"],
  st="① (A): 뒤에 동사({0})가 오는 주어 자리다. 우리말 ‘~는’ → 주격 {1}. → ② (B): 뒤에 명사({2})가 온다. 우리말 ‘~의’ → 소유격 {3}. → ③ 정답은 {n}.",
  R=("is", "He", "pizza", "His"), B=("are", "We", "room", "Our"), C=("am", "I", "pencil", "My"), D=("is", "She", "picture", "Her"), E=("are", "You", "bag", "Your"), F=("are", "They", "bags", "Their"))
RV(7, 15, "E", v="수정(내용)", why="정답 ② She - Her 유일 확인. 다만 정답과 문장의 짜임이 D(She - Her)와 같다(유형 간 중복). 원문항의 우리말 해석도 빠져 있다.", fix="대명사를 바꾸고 우리말 해석을 붙임")

X(7, 16, r="be동사의 현재형: I am / you, we, they are / he, she, it(한 사람·한 개) is.",
  n=["is는 he, she, it에 쓰므로", "are는 you, we, they에 쓰므로", "주어 I에 맞는 am이므로", "be는 원형이라 그대로 쓸 수 없으므로", "둘째 문장이 현재(want)인데 과거형 was를 쓸 수 없으므로"],
  st="① 주어를 본다: {0}. → ② 둘째 문장({1})이 현재의 일이므로 현재형을 쓴다. → ③ 정답은 {a}.",
  R=("I → am", "I want ~"), B=("Tom(한 사람) → is", "He wants ~"), C=("She → is", "She likes ~"), D=("Mina(한 사람) → is", "She has ~ now"), E=("They → are", "They want ~"), F=("We → are", "Let's go now"))

X(7, 17, r="가까운 것: this(하나), these(여럿). 먼 것: that(하나), those(여럿). 앞에서 말한 것: it(하나), they(여럿).",
  n=["This는 가까운 하나이므로", "That은 먼 하나이므로", "They는 ‘그것들’이므로", "Those는 ‘저것들’이므로", "These가 ‘이것들’이므로"],
  st="① 우리말의 첫 낱말을 본다: ‘{0}’. → ② 가까운지 먼지, 하나인지 여럿인지 가른다: {1}. 동사({2})도 수와 맞는지 확인한다. → ③ 정답은 {a}.",
  R=("이것들은", "가까운 여럿", "aren't"), B=("저것들은", "먼 여럿", "aren't"), C=("그것들은", "앞에서 말한 여럿", "aren't"), D=("이것은", "가까운 하나", "isn't"), E=("저것은", "먼 하나", "isn't"), F=("그것은", "앞에서 말한 하나", "isn't"))
RV(7, 17, "E", v="수정(내용)", why="정답 ② They 유일 확인. 다만 우리말(그것들은 내 ○○들이 아니야)과 정답(They)이 C와 같다(유형 간 중복). 제시문에 원문항에 없는 설명도 붙었다.", fix="다른 지시대명사가 정답이 되게")
RV(7, 17, "F", v="수정(내용)", why="정답 ② Those 유일 확인. 다만 우리말(저것들은 내 ○○들이 아니야)과 정답(Those)이 B와 같다(유형 간 중복).", fix="다른 대명사가 정답이 되게")

X(7, 18, r="be동사 의문문은 Am/Is/Are + 주어 ~?이고, 대답의 be동사는 대답의 주어에 맞춘다. No로 답하면 not을 붙인다.",
  n=["단수 주어 the school에 Are를 쓸 수 없으므로", "No로 답했으므로 is가 아니라 isn't를 써야 하므로", "the school에 Is, No 대답의 it에 isn't가 알맞으므로", "the school과 it에 Are, aren't를 쓸 수 없으므로", "대답의 주어 it에 am not을 쓸 수 없으므로"],
  st="① 질문의 주어: {0}. → ② 대답: {1}. → ③ 정답은 {a}.",
  R=("the school(한 개) → Is", "No, it → isn't"), B=("the books(여럿) → Are", "Yes, they → are"), C=("you → Are", "Yes, I → am"), D=("I → Am", "No, you → aren't"), E=("the boys(여럿) → Are", "No, they → aren't"),
  F=("Jane(한 사람) → Is", "Yes, she → is"))

X(7, 19, r="be동사는 주어에 맞춘다: I am / 한 사람·한 개(he, she, it) is / you와 여럿(we, they, A and B) are.",
  n=["문장의 첫머리라서가 아니라 주어에 따라 정하므로", "주어 they가 여럿이라 Are를 쓰므로", "be동사는 your가 아니라 주어 they에 맞추므로", "의문문도 주어에 따라 Am/Is/Are를 쓰므로", "대소문자는 be동사를 고르는 기준이 아니므로"],
  st="① be동사를 정하는 것은 주어다. 이 문장의 주어는 {0}. → ② {1} → ③ 주어의 인칭·수를 이유로 든 것을 고른다. 정답은 {n}.",
  R=("they", "they는 여러 명이므로 Are다."), B=("she", "she는 나나 너가 아닌 한 사람이므로 Is다."), C=("Tom and Ben", "두 사람이므로 Are다."), D=("the children", "여러 명이므로 Are다."), E=("we", "we는 여러 명이므로 Are다."),
  F=("I", "I의 짝은 Am이다."))
RV(7, 19, "B", v="수정(내용)", why="정답 ② 유일 확인. 다만 오답이 문장과 관계없는 일반 규칙(‘의문문은 항상 Are로 시작’, ‘문장 첫 글자는 항상 대문자’ 등)이어서 정답만 문장의 주어(she)를 말해 눈에 띄고, 정답 위치도 원문항과 같다(②). C·E·F가 이 오답을 되풀이한다. 밑줄도 없다.", fix="학생 수준의 그럴듯한 오해로 오답을 새로, 밑줄을 되살림")

X(7, 20, r="these/those 뒤에는 are + 복수 명사, this/that 뒤에는 is + 단수 명사를 쓴다.",
  n=["Those + are + 복수 명사로 옳으므로", "those + are + 복수 명사로 옳으므로", "Those + are + 복수 명사로 옳으므로", "Those 뒤에는 is가 아니라 are를 써야 하므로", "틀린 곳이 없는 문장이므로"],
  st="① 문장마다 지시어(this/that/these/those), be동사, 명사를 차례로 본다. → ② 셋의 수(하나/여럿)가 모두 같은지 견준다. → ③ {0} 정답은 {n}.",
  R="④ Those(여럿) + is(하나)라 맞지 않는다.", B="② These(여럿) + box(하나)라 맞지 않는다.", C="③ This(하나) + are + books(여럿)라 맞지 않는다.", D="④ Those(여럿) + doll(하나)이라 맞지 않는다.",
  E="⑤ These(여럿) + is(하나)라 맞지 않는다.", F="① Those 뒤에 am을 쓸 수 없다. am은 I에만 쓴다.")
RV(7, 20, "B", fx=True, why="수정 예시의 ③(Those are my boxes.)과 ④(Those are his cars.)가 원문항 ③·①과 똑같은 문장이어서 다른 문장으로 바꿨다.")
RV(7, 20, "C", fx=True, why="수정 예시의 틀린 문장(These is my books.)이 E의 틀린 문장(These is my notebooks.)과 거의 같아 다른 오류(This are my books.)로 바꿨다.")
